mapper.select:
#         根据时间获取全部支出数据,并根据category_id进行汇总
        SELECT
            category_id,
            SUM(amount) AS total_amount
        FROM transactions
        where user_id = #{uid}
          and type = 'EXPENSE'
        and date BETWEEN #{start} AND #{end}
        GROUP BY category_id;

SELECT
    date,
    type,
    SUM(amount) AS total_amount
FROM transactions
where user_id = #{uid}
  and date BETWEEN #{start} AND #{end}
GROUP BY date,type;

SELECT
    date,
    type,
    SUM(amount) AS total_amount
FROM transactions
where user_id = #{uid}
  and date BETWEEN #{start} AND #{end}
  and type = 'INCOME'
GROUP BY date,type;
